module counter_sva_generated_tb;

    reg clk;
    reg reset;
    wire [3:0] count;

    // Connect the original counter RTL
    counter dut (
        .clk(clk),
        .reset(reset),
        .count(count)
    );

    // Clock generation
    initial clk = 0;
    always #5 clk = ~clk;

    // Prevent $past from being used before a valid sample exists
    bit past_valid = 0;

    always @(posedge clk)
        past_valid <= 1;

    // Load the assertions generated by Qwen
    `include "counter_assertions.sv"

    // Test sequence
    initial begin
        $display("===== AI-GENERATED SVA TEST =====");

        reset = 1;

        repeat (2) @(negedge clk);

        reset = 0;

        repeat (20) @(negedge clk);

        $display("===== AI-GENERATED SVA TEST COMPLETED =====");
        $finish;
    end

endmodule
